glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
attribute vec3 a_position;
attribute vec2 a_uv0;
attribute vec4 a_color;
varying vec2 v_uv;
varying vec4 v_color;
void main () {
    v_uv = a_uv0;
    v_color = a_color;
    gl_Position = cc_matViewProj * vec4(a_position, 1.0);
}

glsl3.frag:
precision highp float;
varying vec2 v_uv;
varying vec4 v_color;
uniform sampler2D texture;
uniform MyUniform {
  vec4 colorRGB;
};
void main () {
    vec4 texColor = texture2D(texture, v_uv);
    float index = floor(texColor.r * 255.0 + 0.5);
    if (index > 0.0) {
      gl_FragColor = colorRGB * v_color;
    } else {
      gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0);
    }
}

